import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import { git, gitOk } from "../../src/git/exec.ts";
import { groupsHoldingPath } from "../../src/schema/identity.ts";
import type { ReviewDocument, ReviewGroup, Source } from "../../src/schema/types.ts";
import type { EvalExpect } from "./case.ts";
import {
  collectFrozenUrls,
  normalizeUrl,
  parseGithubCommitUrl,
  shaInRange,
  type GithubRepo,
} from "./github.ts";

export type CheckFailure = {
  check: string;
  message: string;
};

export type DeterministicReport = {
  failures: CheckFailure[];
  lints: string[];
  /** Words the review wrote for the reader. Copied PR comment bodies do not count. */
  words: number;
  dirtyWorktree: boolean;
  why: "present" | "absent";
  parts: number;
  groups: number;
  size: ReviewDocument["size"];
  togetherOk: number;
  togetherTotal: number;
  apartOk: number;
  apartTotal: number;
  partsTogetherOk: number;
  partsTogetherTotal: number;
  partsApartOk: number;
  partsApartTotal: number;
};

const EM_DASH = /[\u2013\u2014]/u;
const PATH_TOKEN = /(?:[\w.-]+\/)+[\w.-]+|\b[\w-]{2,}\.[a-z]{1,5}\b/gu;
const SUMMARY_PATHS_MAX = 3;

export async function worktreeDirty(cwd: string): Promise<boolean> {
  const status = (await git(cwd, ["status", "--porcelain"])).trim();
  return status !== "";
}

export async function loadFrozenSourceValues(sourcesDir: string): Promise<unknown[]> {
  const names = await readdir(sourcesDir);
  const values: unknown[] = [];
  for (const name of names.sort((a, b) => a.localeCompare(b))) {
    if (!name.endsWith(".json")) {
      continue;
    }
    values.push(JSON.parse(await readFile(join(sourcesDir, name), "utf8")));
  }
  return values;
}

export async function runDeterministicChecks(opts: {
  cwd: string;
  document: ReviewDocument;
  expect?: EvalExpect;
  frozen: unknown[];
  repo?: GithubRepo;
}): Promise<DeterministicReport> {
  const failures: CheckFailure[] = [];
  const dirtyWorktree = await worktreeDirty(opts.cwd);
  if (dirtyWorktree) {
    failures.push({ check: "worktree", message: "producer left the work tree dirty" });
  }

  const why: "present" | "absent" =
    opts.document.why !== undefined && opts.document.why.trim() !== "" ? "present" : "absent";
  const parts = distinctParts(opts.document.groups);
  const groups = opts.document.groups.length;
  const size = opts.document.size;
  const expect = opts.expect ?? {};

  if (expect.why !== undefined && expect.why !== why) {
    failures.push({ check: "why", message: `expected why ${expect.why}, got ${why}` });
  }
  failures.push(...rangeFailures("parts", parts, expect.parts));
  failures.push(...rangeFailures("groups", groups, expect.groups));
  failures.push(...crossPartDependsOn(opts.document.groups));
  if (expect.size !== undefined && !expect.size.includes(size)) {
    failures.push({
      check: "size",
      message: `expected size ${expect.size.join("|")}, got ${size}`,
    });
  }
  if (expect.sourceKinds !== undefined) {
    const kinds = new Set((opts.document.sources ?? []).map((source) => source.kind));
    const missing = expect.sourceKinds.filter((kind) => !kinds.has(kind));
    if (missing.length > 0) {
      failures.push({
        check: "sourceKinds",
        message: `missing source kinds: ${missing.join(", ")}`,
      });
    }
  }

  const allowed = new Set<string>();
  for (const value of opts.frozen) {
    for (const url of collectFrozenUrls(value)) {
      allowed.add(url);
    }
  }
  for (const source of opts.document.sources ?? []) {
    failures.push(...sourceFailures(source, allowed));
  }
  failures.push(...(await commitSourceFailures(opts.cwd, opts.document, opts.repo)));

  const together = expect.together ?? [];
  let togetherOk = 0;
  for (const paths of together) {
    if (someGroupCovers(opts.document.groups, paths)) {
      togetherOk += 1;
    } else {
      failures.push({ check: "together", message: `no group holds ${paths.join(", ")} together` });
    }
  }

  const apart = expect.apart ?? [];
  let apartOk = 0;
  for (const pair of apart) {
    if (someGroupCovers(opts.document.groups, pair)) {
      failures.push({ check: "apart", message: `a group holds both ${pair[0]} and ${pair[1]}` });
    } else {
      apartOk += 1;
    }
  }

  const partsTogether = expect.partsTogether ?? [];
  let partsTogetherOk = 0;
  for (const paths of partsTogether) {
    const failure = partsTogetherFailure(opts.document.groups, paths);
    if (failure === undefined) {
      partsTogetherOk += 1;
    } else {
      failures.push({ check: "partsTogether", message: failure });
    }
  }

  const partsApart = expect.partsApart ?? [];
  let partsApartOk = 0;
  for (const pair of partsApart) {
    const failure = partsApartFailure(opts.document.groups, pair);
    if (failure === undefined) {
      partsApartOk += 1;
    } else {
      failures.push({ check: "partsApart", message: failure });
    }
  }

  if (
    expect.mechanicalPaths !== undefined &&
    !someGroupCovers(opts.document.groups, expect.mechanicalPaths)
  ) {
    failures.push({
      check: "mechanical",
      message: `no one group holds mechanical paths ${expect.mechanicalPaths.join(", ")}`,
    });
  }

  return {
    failures,
    lints: proseLints(opts.document),
    words: reviewWords(opts.document),
    dirtyWorktree,
    why,
    parts,
    groups,
    size,
    togetherOk,
    togetherTotal: together.length,
    apartOk,
    apartTotal: apart.length,
    partsTogetherOk,
    partsTogetherTotal: partsTogether.length,
    partsApartOk,
    partsApartTotal: partsApart.length,
  };
}

function rangeFailures(
  check: "parts" | "groups",
  value: number,
  range: EvalExpect["parts"],
): CheckFailure[] {
  if (range === undefined) {
    return [];
  }
  if (range.max < range.min) {
    return [{ check, message: `${check}.max ${range.max} is below min ${range.min}` }];
  }
  if (value < range.min || value > range.max) {
    return [{ check, message: `expected ${range.min} to ${range.max} ${check}, got ${value}` }];
  }
  return [];
}

/** The skill keeps `dependsOn` inside one story; a cross-part edge is a false chain. */
function crossPartDependsOn(groups: ReviewGroup[]): CheckFailure[] {
  const partById = new Map(groups.map((group) => [group.id, group.part]));
  return groups.flatMap((group) =>
    (group.dependsOn ?? [])
      .filter((dep) => partById.has(dep) && partById.get(dep) !== group.part)
      .map((dep) => ({
        check: "dependsOn",
        message: `group ${group.id} (${group.part ?? "no part"}) depends on ${dep} (${partById.get(dep) ?? "no part"})`,
      })),
  );
}

function distinctParts(groups: ReviewGroup[]): number {
  return new Set(groups.map((group) => group.part).filter((part) => part !== undefined)).size;
}

function someGroupCovers(groups: ReviewGroup[], paths: readonly string[]): boolean {
  return groups.some((group) =>
    paths.every((path) => groupsHoldingPath(groups, path).includes(group)),
  );
}

type PartKey = ReviewGroup["part"];

/**
 * Groups with no `part` share one unnamed story, as in the schema's `dependsOn` rule,
 * so a one-story review holds every path in one part.
 */
function partsHoldingPath(groups: ReviewGroup[], path: string): Set<PartKey> {
  return new Set(groupsHoldingPath(groups, path).map((group) => group.part));
}

function partLabel(part: PartKey): string {
  return part === undefined ? "the unnamed story" : `part "${part}"`;
}

/** Unlike group-level `apart`, a path no group holds fails: a lockfile probe would pass for free. */
function unheldPaths(groups: ReviewGroup[], paths: readonly string[]): string | undefined {
  const unheld = paths.filter((path) => groupsHoldingPath(groups, path).length === 0);
  return unheld.length === 0 ? undefined : `no group holds ${unheld.join(", ")}`;
}

function partsTogetherFailure(groups: ReviewGroup[], paths: readonly string[]): string | undefined {
  const unheld = unheldPaths(groups, paths);
  if (unheld !== undefined) {
    return unheld;
  }
  const [first = new Set<PartKey>(), ...rest] = paths.map((path) => partsHoldingPath(groups, path));
  const shared = [...first].some((part) => rest.every((parts) => parts.has(part)));
  return shared ? undefined : `no part holds ${paths.join(", ")} together`;
}

function partsApartFailure(
  groups: ReviewGroup[],
  [left, right]: readonly [string, string],
): string | undefined {
  const unheld = unheldPaths(groups, [left, right]);
  if (unheld !== undefined) {
    return unheld;
  }
  const rightParts = partsHoldingPath(groups, right);
  const shared = [...partsHoldingPath(groups, left)].filter((part) => rightParts.has(part));
  return shared.length === 0
    ? undefined
    : `${shared.map(partLabel).join(" and ")} holds both ${left} and ${right}`;
}

function sourceFailures(source: Source, allowed: Set<string>): CheckFailure[] {
  if (source.kind === "transcript") {
    return [
      { check: "sources", message: `transcript source "${source.id}" is invented in this harness` },
    ];
  }
  if (source.url === undefined) {
    return [];
  }
  if (source.kind === "commit" && parseGithubCommitUrl(source.url) !== undefined) {
    return [];
  }
  if (!allowed.has(normalizeUrl(source.url))) {
    return [
      {
        check: "sources",
        message: `source "${source.id}" url is not in the frozen set: ${source.url}`,
      },
    ];
  }
  return [];
}

/** A commit `label` is the subject line. Producers often drop the conventional final period. */
function commitLabelMatchesSubject(label: string, subjects: readonly string[]): boolean {
  const bareLabel = stripOneTrailingPeriod(label);
  return subjects.some(
    (subject) => subject === label || stripOneTrailingPeriod(subject) === bareLabel,
  );
}

function stripOneTrailingPeriod(text: string): string {
  return text.endsWith(".") ? text.slice(0, -1) : text;
}

async function commitSourceFailures(
  cwd: string,
  document: ReviewDocument,
  repo: GithubRepo | undefined,
): Promise<CheckFailure[]> {
  const commits = (document.sources ?? []).filter((source) => source.kind === "commit");
  if (commits.length === 0) {
    return [];
  }
  const range = `${document.source.baseRef}..${document.source.headRef}`;
  const shas = (await git(cwd, ["log", "--format=%H", "--end-of-options", range]))
    .trim()
    .split("\n")
    .filter(Boolean);
  const subjects = (await git(cwd, ["log", "--format=%s", "--end-of-options", range]))
    .trim()
    .split("\n");
  const shaSet = new Set(shas);
  const failures: CheckFailure[] = [];
  for (const source of commits) {
    if (source.url !== undefined) {
      const parsed = parseGithubCommitUrl(source.url);
      if (parsed !== undefined) {
        if (repo !== undefined && (parsed.owner !== repo.owner || parsed.repo !== repo.repo)) {
          failures.push({
            check: "sources",
            message: `commit source "${source.id}" url is not this repo: ${source.url}`,
          });
          continue;
        }
        if (!shaInRange(parsed.sha, shas)) {
          failures.push({
            check: "sources",
            message: `commit source "${source.id}" url sha is not in ${range}: ${source.url}`,
          });
          continue;
        }
      }
    }
    if (
      commitLabelMatchesSubject(source.label, subjects) ||
      shas.some((sha) => sha.startsWith(source.label) || source.label.startsWith(sha.slice(0, 7)))
    ) {
      continue;
    }
    const exists = await gitOk(cwd, ["cat-file", "-e", `${source.label}^{commit}`]);
    if (exists) {
      const resolved = (
        await git(cwd, ["rev-parse", "--verify", `${source.label}^{commit}`])
      ).trim();
      if (shaSet.has(resolved)) {
        continue;
      }
    }
    failures.push({
      check: "sources",
      message: `commit source "${source.id}" label is not in ${range}: ${source.label}`,
    });
  }
  return failures;
}

export function reviewWords(document: ReviewDocument): number {
  return documentFields(document).reduce((total, field) => total + wordCount(field.text), 0);
}

export function proseLints(document: ReviewDocument): string[] {
  const lints: string[] = [];
  for (const field of documentFields(document)) {
    if (EM_DASH.test(field.text)) {
      lints.push(`${field.where} contains an em dash or en dash`);
    }
    for (const sentence of sentences(field.text)) {
      const words = wordCount(sentence);
      if (words > 25) {
        lints.push(`${field.where} has a ${words}-word sentence`);
      }
    }
  }
  for (const field of summaryFields(document)) {
    const count = sentences(field.text).length;
    if (count > field.maxSentences) {
      lints.push(`${field.where} has ${count} sentences`);
    }
    const paths = field.text.match(PATH_TOKEN)?.length ?? 0;
    if (paths > SUMMARY_PATHS_MAX) {
      lints.push(`${field.where} names ${paths} paths`);
    }
  }
  return lints;
}

/** The skill asks for at most two sentences per group summary and two for the document. */
function summaryFields(
  document: ReviewDocument,
): { where: string; text: string; maxSentences: number }[] {
  return [
    { where: "summary", text: document.summary, maxSentences: 2 },
    ...document.groups.map((group) => ({
      where: `group ${group.id} summary`,
      text: group.summary,
      maxSentences: 2,
    })),
  ];
}

function documentFields(document: ReviewDocument): { where: string; text: string }[] {
  const fields: { where: string; text: string }[] = [
    { where: "title", text: document.title },
    { where: "summary", text: document.summary },
  ];
  if (document.why !== undefined) {
    fields.push({ where: "why", text: document.why });
  }
  for (const bullet of document.lookFor ?? []) {
    fields.push({ where: "document lookFor", text: bullet });
  }
  for (const source of document.sources ?? []) {
    if (source.gist !== undefined) {
      fields.push({ where: `source ${source.id} gist`, text: source.gist });
    }
  }
  for (const part of document.parts ?? []) {
    fields.push({ where: `part ${part.name} summary`, text: part.summary });
  }
  for (const group of document.groups) {
    fields.push({ where: `group ${group.id} title`, text: group.title });
    if (group.why !== undefined) {
      fields.push({ where: `group ${group.id} why`, text: group.why });
    }
    fields.push({ where: `group ${group.id} summary`, text: group.summary });
    if (group.attention !== undefined) {
      fields.push({ where: `group ${group.id} attention`, text: group.attention.note });
    }
    for (const question of group.questions ?? []) {
      fields.push({ where: `group ${group.id} question`, text: question });
    }
    for (const range of group.focus ?? []) {
      fields.push({ where: `group ${group.id} focus`, text: range.caption });
    }
    for (const note of group.notes ?? []) {
      fields.push({ where: `group ${group.id} note`, text: note.body });
    }
    for (const [path, note] of Object.entries(group.fileNotes ?? {})) {
      fields.push({ where: `group ${group.id} file note ${path}`, text: note });
    }
  }
  return fields;
}

function sentences(text: string): string[] {
  return text
    .split(/(?<=[.!?])\s+/u)
    .map((item) => item.trim())
    .filter((item) => item !== "");
}

function wordCount(text: string): number {
  return text.split(/\s+/u).filter((item) => item !== "").length;
}
